cypress_script:
describe('Select Menu Widgets', () => {
  it('should select a color from the dropdown', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('#oldSelectMenu').select('Red');
    cy.url().should('include', '/select-menu');
  });
  it('should not change the URL when selecting an option without interaction', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('#oldSelectMenu').select('');
    cy.url().should('include', '/select-menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Select Menu Widgets', () => {
  test('should select a color from the dropdown', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('#oldSelectMenu', 'red');
    await expect(page).toHaveURL(/select-menu/);
  });
  test('should not change the URL when selecting an option without interaction', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('#oldSelectMenu', '');
    await expect(page).toHaveURL(/select-menu/);
  });
});
